def pair_scan_steps(a):
    a, steps = list(a), 0
    for i in range(0, len(a), 2):
        if a[i] % 2 == 1:
            j = 1
            while a[j] % 2 == 1:
                j += 2
                steps += 1
            a[i], a[j] = a[j], a[i]
    return steps


