#include <string>
#include <algorithm>
using namespace std;
int nge3SortSuffix(int n) {
    string s = to_string(n);
    int i = (int)s.size() - 2;
    while (i >= 0 && s[i] >= s[i + 1]) --i;
    if (i < 0) return -1;
    int j = (int)s.size() - 1;
    while (s[j] <= s[i]) --j;
    swap(s[i], s[j]);
