#include <vector>
#include <algorithm>
using namespace std;
#include <iostream>

int rotationMatching(const vector<int>& a, const vector<int>& b) {
    int n = (int)a.size();
    vector<int> pa(n + 1), pb(n + 1), cnt(n, 0);
    for (int i = 0; i < n; ++i) pa[a[i]] = i;
    for (int i = 0; i < n; ++i) pb[b[i]] = i;
    for (int v = 1; v <= n; ++v)
        cnt[((pa[v] - pb[v]) % n + n) % n]++;      // keep the residue non-negative
    return *max_element(cnt.begin(), cnt.end());
}

int main() {
    vector<int> a{1, 3, 2, 4}, b{4, 2, 3, 1};
    cout << rotationMatching(a, b) << "\n";         // 2
    return 0;
}
